def decrypt(encrypted_text: str, n: int) -> str:
    if encrypted_text is None or encrypted_text == '' or n <= 0:
        return encrypted_text
    if n % 2 == 0:
        return encrypted_text
    result = []
    even_chars = encrypted_text[::2]
    odd_chars = encrypted_text[1::2]
    for i in range(len(even_chars)):
        result.append(odd_chars[i])
